-- ============================================
-- TIPOS_DOCUMENTO: cédula, pasaporte, carnet de extranjería, acta de nacimiento ...
-- ============================================
CREATE TABLE IF NOT EXISTS "TIPOS_DOCUMENTO" (
    "ID_TIPO_DOCUMENTO" INT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_TIPOS_DOCUMENTO" PRIMARY KEY,
    "NOMBRE" VARCHAR(80) NOT NULL CONSTRAINT "UQ_TIPOS_DOCUMENTO_NOMBRE" UNIQUE,
    "ACTIVO" BOOLEAN NOT NULL DEFAULT TRUE
);
